CREATE TABLE `organizations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`name` VARCHAR(120) NOT NULL,`slug` VARCHAR(63) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,`status` ENUM('active','archived') NOT NULL,`timezone` VARCHAR(64) CHARACTER SET ascii NOT NULL,`data_retention_days` SMALLINT UNSIGNED NOT NULL,`default_workspace_id` CHAR(36) CHARACTER SET ascii NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_organizations_slug`(`slug`),KEY `idx_organizations_status_updated`(`status`,`updated_at`),CONSTRAINT `fk_organizations_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
